/**
 * Html5Qrcode Camera Scanner Wrapper Helper for biMBA AIUEO
 */
class Html5QrcodeScanner {
    constructor(elementId, config, verbose) {
        this.elementId = elementId;
        this.config = config || {};
        this.isScanning = false;
        this.stream = null;
    }

    render(onSuccess, onError) {
        const container = document.getElementById(this.elementId);
        if (!container) return;

        container.innerHTML = `
            <div style="text-align:center; padding:16px;">
                <video id="qrVideoElement" style="width:100%; max-height:260px; object-fit:cover; border-radius:8px; display:none;"></video>
                <div id="qrCamFallback" style="padding: 20px;">
                    <span class="material-symbols-outlined" style="font-size: 56px; color: #FFFFFF;">videocam</span>
                    <p style="font-family: var(--font-sans); font-size: 13px; color: #FFFFFF; margin-top: 8px;">Scanner Kamera Aktif</p>
                    <button type="button" id="startCamBtn" class="btn btn-secondary btn-sm" style="margin-top: 12px;">
                        Aktifkan Kamera Webcam
                    </button>
                </div>
            </div>
        `;

        const startBtn = document.getElementById('startCamBtn');
        const video = document.getElementById('qrVideoElement');
        const fallback = document.getElementById('qrCamFallback');

        if (startBtn) {
            startBtn.addEventListener('click', async () => {
                try {
                    this.stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
                    video.srcObject = this.stream;
                    video.style.display = 'block';
                    fallback.style.display = 'none';
                    await video.play();
                    this.isScanning = true;
                } catch (err) {
                    alert('Tidak dapat mengakses kamera: ' + err.message + '. Gunakan input payload manual.');
                    if (onError) onError(err);
                }
            });
        }
    }

    clear() {
        if (this.stream) {
            this.stream.getTracks().forEach(track => track.stop());
        }
    }
}
